begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select has_table('public','feedback_events','Se registra una comparación por envío confirmado');
select has_column('public','feedback_events','metrics','Las métricas no contienen texto');
select has_index('public','feedback_events','feedback_events_pending_idx','Los reintentos están indexados');
select has_index('public','feedback_events','feedback_events_draft_owner_idx','La referencia al borrador incluye propietario');
select has_index('public','feedback_events','feedback_events_run_owner_idx','La referencia a la generación incluye propietario');
select ok((select relrowsecurity from pg_class where oid='public.feedback_events'::regclass),'RLS habilitado');
select ok(not has_table_privilege('anon','public.feedback_events','SELECT'),'No hay acceso anónimo');
select ok(not has_table_privilege('authenticated','public.feedback_events','INSERT'),'El navegador no crea feedback');
select ok(not has_column_privilege('authenticated','public.feedback_events','lease_id','SELECT'),'Los leases son privados');
select ok(not has_function_privilege('authenticated','public.claim_reply_comparisons(integer,integer)','EXECUTE'),'La adquisición es exclusiva del worker');
select ok(not has_function_privilege('authenticated','public.load_reply_comparison_original(uuid,uuid,uuid,uuid)','EXECUTE'),'El navegador no obtiene el texto original');
select ok(not has_function_privilege('anon','public.finish_reply_comparison(uuid,uuid,uuid,uuid,jsonb)','EXECUTE'),'No se guardan métricas anónimas');
select ok(not has_function_privilege('authenticated','public.finish_reply_comparison(uuid,uuid,uuid,uuid,jsonb)','EXECUTE'),'El navegador no altera métricas');
select ok(has_function_privilege('service_role','public.finish_reply_comparison(uuid,uuid,uuid,uuid,jsonb)','EXECUTE'),'El worker autorizado completa comparaciones');
select has_view('public','reply_comparison_daily','Existen agregados diarios reproducibles');
select ok((select 'security_invoker=true'=any(reloptions) from pg_class where oid='public.reply_comparison_daily'::regclass),'Los agregados respetan las políticas RLS');
select ok(not has_table_privilege('anon','public.reply_comparison_daily','SELECT'),'Los agregados no son públicos');
select * from finish();
rollback;
